describe("SL-008 newest open task first", () => {
  let server: Running;

  before(async () => {
    server = await startServer();
  });
  after(async () => {
    await server?.stop();
  });

  it("lists the most recently created task first", async () => {
    for (const title of ["First", "Second", "Third"]) {
      assert.equal((await createTask(server, title)).status, 201);
    }
    const titles = (await listTasks(server)).map((t) => t.title);
    assert.deepEqual(titles, ["Third", "Second", "First"]);
  });

  it("the page has an empty-state message that the script toggles", async () => {
    const html = await (await fetch(`${server.baseUrl}/`)).text();
    const script = await (await fetch(`${server.baseUrl}/app.js`)).text();
    assert.match(html, /<p[^>]+id=["']task-empty["']/);
    assert.match(script, /task-empty/);
  });
});
